package webbundle_test

import (
	"fmt"
	"log"
	"os"
	"path/filepath"

	"github.com/cplieger/go/httpserver/v2"
	"github.com/cplieger/go/webbundle"
)

func ExampleRenderPages() {
	pages := []httpserver.Page{
		{Name: "library", Pattern: "/library"},
		{Name: "entry", Pattern: "/library/{id}"},
	}
	table, err := webbundle.RenderPages(pages, "/api")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Print(string(table))
	// Output:
	// // Code generated by webbundle. DO NOT EDIT.
	//
	// export const PAGES = {
	//   library: "/library",
	//   entry: "/library/{id}",
	// } as const;
	// export const API_PREFIX = "/api";
}

func ExampleBuildStyle() {
	src, err := os.MkdirTemp("", "webbundle-example-")
	if err != nil {
		log.Fatal(err)
	}
	defer os.RemoveAll(src)
	files := map[string]string{
		"base.css": ".page { margin: 0 auto; }\n",
		"app.css":  "@import \"./base.css\";\n.title { font-weight: 700; }\n",
	}
	for name, body := range files {
		if err := os.WriteFile(filepath.Join(src, name), []byte(body), 0o644); err != nil {
			log.Fatal(err)
		}
	}
	css, err := webbundle.BuildStyle(webbundle.Stylesheet{Src: src, Path: "app.css"})
	if err != nil {
		log.Fatal(err)
	}
	fmt.Print(string(css))
	// Output:
	// .page{margin:0 auto}.title{font-weight:700}
}
